mapper.select:
SELECT user_id, start_time, end_time FROM leave_request
WHERE status = 'APPROVED' AND start_time < #{end} AND end_time > #{start}
AND user_id IN #{userId}
ORDER BY user_id, start_time, end_time

SELECT l.id, l.enterprise_id, l.user_id, l.department_id, l.leave_type, l.start_time,
l.end_time, l.reason, l.status, l.reviewer_id, l.review_comment, l.reviewed_at, l.create_time, l.update_time
FROM leave_request l

    INNER JOIN sys_user u ON u.id = l.user_id
    INNER JOIN sys_department d ON d.id = u.department_id

WHERE 1 = 1
AND l.user_id = #{userId}
AND d.is_enabled = 1 AND l.user_id != #{managerId}
    AND CASE WHEN d.manager_user_id = l.user_id THEN d.self_approver_user_id ELSE d.manager_user_id END = #{managerId}
AND l.status = #{status}
ORDER BY l.create_time DESC, l.id DESC

mapper.update:
UPDATE leave_request l
INNER JOIN sys_user u ON u.id = l.user_id
INNER JOIN sys_department d ON d.id = u.department_id
SET l.status = #{status}, l.reviewer_id = #{reviewerId}, l.review_comment = #{comment},
    l.reviewed_at = #{now}, l.update_time = #{now}
WHERE l.id = #{id} AND l.status = 'PENDING' AND l.user_id != #{reviewerId}
  AND CASE WHEN d.manager_user_id = l.user_id THEN d.self_approver_user_id ELSE d.manager_user_id END = #{reviewerId}
  AND d.is_enabled = 1
